(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"আজ সবকিছু করতে হবে না। পরের ছোট্ট কাজটাই যথেষ্ট।\", \"ক্লান্ত হওয়া মানে হেরে যাওয়া নয়। তুমি ক্লান্ত, কারণ তুমি প্রতিদিন পাশে থাকো।\", \"থালাবাসন অপেক্ষা করতে পারে। পাঁচ মিনিট বসার অধিকার তোমার আছে।\", \"রাতে সিরিয়াল খাওয়ানোও পরিবারের পেট ভরানোই।\", \"বিশ্রাম অর্জন করতে হয় না। তুমি এখনই একটু বিশ্রাম নিতে পারো।\", \"কোনো কোনো দিন জয় মানে সবাই ঘুমের সময় পর্যন্ত ঠিকঠাক পৌঁছেছে। এটা সত্যিকারের জয়।\", \"তুমি যা করো, কেউ তার সবটা দেখে না। আমি দেখি।\", \"অগোছালো ঘর আর ভালোবাসায় বড় হওয়া সন্তান। এটা ভালো বিনিময়।\", \"কঠিন দিনে তোমার সেরাটা অন্যরকম দেখায়, তবুও সেটা গোনা হয়।\", \"একটা গভীর শ্বাস। কাঁধ দুটো আলগা করো। তুমি ভালোই করছ।\", \"আজ প্রত্যাশা একটু কমিয়ে রাখা ঠিক আছে। অন্য কোনো দিন আবার বাড়িয়ে নিও।\", \"সাহায্য চাওয়া শক্তির কাজ, দুর্বলতার নয়।\", \"আরও একটা কাজে না বলার অধিকার তোমার আছে।\", \"আজ যদি একা লেগে থাকে, তুমি একমাত্র মা নও যার এমন লেগেছে। আমরা অনেকে।\", \"তোমার এমন একজন বন্ধু প্রাপ্য, যে জিজ্ঞেস করবে তুমি কেমন আছ আর উত্তরের জন্য অপেক্ষা করবে।\", \"আগে নিজে যোগাযোগ করা ঠিক আছে। বেশিরভাগ মা আশা করে থাকে কেউ একজন করবে।\", \"কেউ খেয়াল করছে না মনে হলেও, তুমি গুরুত্বহীন নও। তুমি খুব গুরুত্বপূর্ণ।\", \"তোমার অনুভূতিগুলো বোঝা যায়। তুমি বাড়াবাড়ি নও।\", \"এখানে তোমার কঠিন দিনটা ব্যাখ্যা করতে হবে না। আমরা বুঝি।\", \"আরেকজন মাকে \\\"আমারও\\\" লেখা একটা মেসেজ পুরো দিনটা বদলে দিতে পারে।\", \"খাওয়ানো, কাপড় বদলানো, দোল দেওয়া, তারপর আবার। এটা সত্যিকারের কাজ, যদিও মনে হয় শুধু বসে আছ।\", \"তুমি আর তোমার বাচ্চা এখনো একে অপরকে চিনছ। কোনো তাড়া নেই।\", \"নবজাতকের সাথে দিনগুলো লম্বা। এই সময়টা চিরকাল থাকবে না।\", \"আজ যদি শুধু একটা ছোট্ট মানুষকে পেট ভরে খাইয়ে আর উষ্ণ রেখে থাকো, তুমি অনেক বড় কাজ করেছ।\", \"তাড়াতাড়ি আগের মতো হয়ে যেতে হবে না। তুমি যেখানে আছ, সেখানেই থাকতে পারো।\", \"বাচ্চা যেভাবেই খাক, তুমি তার যত্ন নিচ্ছ। এটাই আসল কথা।\", \"ঘুম কম আর ভালোবাসা ভরপুর, দুটোই একসাথে হতে পারে।\", \"বাচ্চাকে কোলে নাও, ঘরের কাজ পড়ে থাকুক। ঘর কোথাও যাচ্ছে না।\", \"দোকানে বাচ্চার কান্নাকাটি তোমাকে খারাপ মা বানায় না। এর মানে শুধু তোমার একটা ছোট্ট বাচ্চা আছে।\", \"ছোটরা সীমা পরীক্ষা করে, কারণ তোমার কাছে তারা নিরাপদ বোধ করে।\", \"আজ তুমি গতকালের চেয়ে এক মিনিট বেশি শান্ত ছিলে। এটা গোনা হয়।\", \"যদি রাগ হয়ে গিয়ে থাকে, একটা জড়িয়ে ধরা আর একটা \\\"সরি\\\" অনেক কিছু ঠিক করে দেয়। আর ওরাও ভালো কিছু শেখে।\", \"চটচটে হাত, জোরে আওয়াজ, বড় বড় অনুভূতি। তুমি একজন পূর্ণ মানুষ গড়ে তুলছ।\", \"এই ঘণ্টার পঞ্চম \\\"কেন?\\\" মানে একটা ছোট্ট মন বেড়ে উঠছে।\", \"সুখের স্মৃতি বানাতে নিখুঁত দিন লাগে না।\", \"জোরে বন্ধ হওয়া দরজা গল্পের শেষ নয়। আলোটা জ্বেলে রাখো।\", \"তোমার কিশোর সন্তান হয়তো বলবে না, কিন্তু তোমার সবসময় পাশে থাকাটা তার কাছে অনেক কিছু।\", \"বাড়িতে শান্ত মানুষটা হওয়া কঠিন কাজ। আর তুমি সেটাই করছ।\", \"কিছু সেরা কথাবার্তা গাড়িতেই হয়। চালিয়ে যাও।\", \"ওরা বড় হতে দূরে সরে, তোমাকে পেছনে ফেলে যেতে নয়।\", \"সব প্রশ্নের উত্তর জানতে হবে না। শোনাটাই অনেকখানি।\", \"বড় সন্তানদেরও এখনো তোমাকে দরকার, শুধু আরও নীরবভাবে।\", \"সবকিছু একা সামলাতে এমন শক্তি লাগে, যা বেশিরভাগ মানুষ কখনো দেখে না।\", \"তোমার সন্তানের জন্য তুমি যথেষ্ট ভালো মা। সবসময়ই ছিলে।\", \"দুটো হাত, একশো কাজ। নিজের প্রতি একটু নরম হও।\", \"তোমার সন্তানেরা তোমাকে দেখে শিখছে, একজন শক্ত আর ভালোবাসায় ভরা মানুষ কেমন হয়।\", \"একটু বিরতি নেওয়া মানে দায়িত্ব ছেড়ে দেওয়া নয়। এভাবেই তুমি এগিয়ে যেতে পারো।\", \"কেউ হিসাব রাখছে না। ভালোবাসা আর পাশে থাকা, এটাই আসল।\", \"শোক আর ভালোবাসা একই জায়গা থেকে আসে। কাউকে মনে পড়া বোঝায় তুমি কতটা ভালোবেসেছিলে।\", \"শোকের কোনো ঠিক সময়সূচি নেই। যতটা সময় দরকার, নাও।\", \"কঠিন বার্ষিকীর দিনগুলোতে নিজের প্রতি ততটাই কোমল হও, যতটা একজন বন্ধুর প্রতি হতে।\", \"মনে দুঃখ নিয়েও তুমি সন্তানদের সাথে হাসতে পারো। দুটোই সত্যি।\", \"তুমি যদি গর্ভ বা সন্তান হারিয়ে থাকো, সেই হারানো সত্যি, আর তোমার ভালোবাসাও।\", \"কোনো দিন শোক চুপচাপ, কোনো দিন খুব জোরালো। দুটোই ঠিক আছে।\", \"টাকার টান মানে ভালোবাসার টান নয়।\", \"তোমার সন্তানেরা কেনা জিনিসের চেয়ে তোমার সাথে কাটানো সময় বেশি মনে রাখবে।\", \"বিল নিয়ে সাহায্যের কথা জিজ্ঞেস করা বুদ্ধিমানের কাজ, লজ্জার নয়। সাহায্যটা তো এর জন্যই আছে।\", \"পার্কে বিনা খরচের একটা বিকেল সপ্তাহের সেরা দিন হয়ে উঠতে পারে।\", \"তুমি টাকাটা আরও এক সপ্তাহ চালিয়ে নিয়েছ। এর জন্য সত্যিকারের দক্ষতা লাগে।\", \"টাকার দুশ্চিন্তা ক্লান্ত করে দেয়। তুমি অনেক কিছু বয়ে বেড়াচ্ছ, তবুও তুমি আছ।\", \"আজ তুমি এক গ্লাস পানি খেয়েছ। সেখান থেকেই শুরু করো।\", \"সবাই দরজা দিয়ে বের হয়েছে। জুতোগুলো হয়তো মেলেনি। তবুও জয়।\", \"যে ফোনটা করতে ভয় পাচ্ছিলে, সেটা করে ফেলেছ। এটা সাহসের কাজ।\", \"আজ তুমি হেসেছ। ওটা আঁকড়ে রাখো।\", \"গরম খাবার, পরিষ্কার জামা, ঘুমের আগে একটা গল্প। ছোট ছোট জিনিস মিলেই শৈশব হয়।\", \"আজ তুমি কারো প্রতি সদয় ছিলে, হোক না সেটা শুধু নিজের প্রতি।\", \"নিখুঁত নয়, এগিয়ে চলা। আজ তুমি এগিয়েছ।\", \"তালিকার একটা কাজ শেষ করেছ। কিছু না হওয়ার চেয়ে একটা বেশি।\", \"তুমি ভালো মা। এ নিয়ে তোমার চিন্তা হওয়াটাই দেখায় তুমি কতটা যত্ন করো।\", \"একদিনে যা করে উঠতে পারো, তুমি তার চেয়ে অনেক বেশি।\", \"তোমার সন্তানদের নিখুঁত মা লাগবে না। তাদের তোমাকে দরকার, আর তুমি তাদের কাছে আছ।\", \"নিজের প্রতি ততটাই ধৈর্য রাখো, যতটা সন্তানদের প্রতি রাখো।\", \"নিজের জায়গা নেওয়ার, কিছু চাওয়ার আর নিজের স্বপ্ন রাখার অধিকার তোমার আছে।\", \"একটা ভুল ভালোবাসা মুছে দেয় না। কাল নতুন শুরু।\", \"তুমি কারো পুরো পৃথিবী, আবার তুমি নিজের মতো একজন মানুষও।\", \"প্রতিটা মুহূর্ত ভালো না লাগাটা ঠিক আছে। তবুও তুমি সন্তানদের পুরো মন দিয়ে ভালোবাসতে পারো।\", \"মা হওয়ার একটাই ঠিক উপায় নেই। তোমার উপায়টাও ঠিক।\", \"বৃক্ষাসনের মতো, একটু টলে যাওয়া ঠিক আছে। তুমি আবার ভারসাম্য খুঁজে পাবে।\", \"তাড়াসনের মতো পা দুটো শক্ত করে রাখো। তুমি যতটা ভাবো, তার চেয়ে বেশি দৃঢ়।\", \"বীরভদ্রাসন দুই: শক্ত পা, খোলা হাত। এটাই তুমি, এই সপ্তাহের মুখোমুখি।\", \"চার গুনে শ্বাস নাও, চার গুনে ছাড়ো। তুমি এখানেই আছ, আর ভালোই করছ।\", \"তারার মতো ছড়িয়ে দাও নিজেকে। জায়গা নেওয়ার অধিকার তোমার আছে।\", \"চওড়া, নিচু হয়ে বসে থাকা কঠিন। লম্বা দিনও তেমনই। আর তুমি টিকে আছ।\", \"তুমি অর্ধচন্দ্রের মতো হেলেও দাঁড়িয়ে থাকতে পারো।\", \"এখনই পায়ের আঙুল ছুঁতে হবে না। প্রতিটা ছোট্ট টানও গোনা হয়।\", \"ত্রিকোণাসন: এক হাত নিচে, এক হাত ওপরে। মাটিতে শক্ত থাকো আর প্রসারিত হতে থাকো।\", \"অনেক রাত হয়েছে। আজ যা হয়নি, তা কাল পর্যন্ত অপেক্ষা করতে পারে।\", \"এই সময়ে বাচ্চার সাথে জেগে আছ? এখন অনেক মা তোমার সাথে জেগে আছে।\", \"ঘর চুপচাপ। এই মুহূর্তটা তোমার। শ্বাস নাও।\", \"আজকের দিনটা তুমি পার করেছ। আজকের জন্য এটুকুই দরকার ছিল।\", \"আজ রাতে মন অস্থির থাকলে, সব লিখে রাখো আর সকাল পর্যন্ত অপেক্ষা করতে দাও।\", \"চোখ দুটোকে বিশ্রাম দাও। কাল আবার নতুন করে শুরু করতে পারবে।\", \"উৎসব আনন্দের পাশাপাশি কঠিনও হতে পারে। এই সময়টা তোমার কাছে যেমনই লাগুক, ঠিক আছে।\", \"খাবারের টেবিল নিখুঁত হতে হবে না। তাকে ঘিরে থাকা মানুষগুলোই আসল।\", \"এ বছর যদি টেবিলে কারো অভাব বোধ করো, নিজের মনের প্রতি কোমল থেকো।\", \"ধন্যবাদ মা, প্রতিটা খাবার, প্রতিটা যাত্রা আর প্রতিটা জড়িয়ে ধরার জন্য।\", \"অতিথি আপ্যায়ন, রান্নাবান্না বা সারাক্ষণ হাসিমুখে থাকতে হবে না। সাদামাটা উৎসবও উৎসব।\", \"এ বছর তোমার সন্তানদের সেরা উপহার হলো তোমার সাথে কাটানো সময়।\", \"ছোট্ট উদযাপনও ভালোবাসায় ভরা। বিশেষ করে তুলতে অনেক টাকা লাগে না।\", \"ঠান্ডা দিন, উষ্ণ আলিঙ্গন। তুমিই তোমার ঘরের উষ্ণ কোণ।\", \"উৎসবের কিছু দৌড়ঝাঁপ বাদ দেওয়া ঠিক আছে। শান্তিও একটা উপহার।\", \"এ বছর এই সময়টা যদি ভারী লাগে, তুমি একা নও। একদিন একদিন করে এগোও।\"]";D.body.appendChild(e)})();
